<template>
 <section class="note-context" aria-label="Complete note encounter and scored treatment plan">
  <div v-if="reviewer" class="note-reviewer"><strong>SUPERVISOR NOTE REVIEW</strong><span>Viewing as {{ reviewer }}</span></div>
  <header><div><span>FICTIONAL CLINICAL NOTE · FULL REVIEW</span><h3>{{ context.client }}</h3><p>{{ context.practice }} · {{ context.date }}</p></div><span class="note-context-type">{{ context.encounter.serviceCode }} · {{ context.encounter.durationMinutes }} minutes</span></header>
  <dl class="note-encounter"><div v-for="field in fields" :key="field[0]"><dt>{{ field[0] }}</dt><dd>{{ field[1] }}</dd></div></dl>
  <div class="note-signatures"><span>{{ providerSigned?'Provider signature simulated':'Provider signature pending' }}</span><span>{{ supervisorSigned?'Supervisor co-signature simulated':'Supervisor co-signature pending' }}</span><span v-if="reviewer">Viewing as {{ reviewer }}</span></div>
  <section class="note-risk" aria-label="Risk and safety assessment"><h4>Risk &amp; safety assessment</h4><p>{{ context.encounter.riskSummary }}</p><p class="note-fiction">Fictional assessment details supplied for this demonstration.</p></section>
  <slot/>
  <section class="note-scores" aria-label="Treatment plan scores recorded with this note"><header><h4>Treatment plan scores recorded with this note</h4><span>1–10 scale</span></header><article v-for="(row,index) in context.scores" :key="`${row.goal}-${row.objective}-${row.rater}-${index}`"><h5>{{ row.goal }} · {{ row.objective }} <span>{{ row.rater }}</span></h5><strong>{{ row.goalText }}</strong><p>{{ row.objectiveText }}</p><dl><div><dt>Start</dt><dd>{{ row.start }}</dd></div><div><dt>Previous session</dt><dd>{{ row.previous }}</dd></div><div class="note-score-current"><dt>This session</dt><dd>{{ row.current??'Not recorded' }}</dd></div><div><dt>Goal</dt><dd>{{ row.target }}</dd></div></dl><small>{{ row.direction==='lower'?'Lower scores are the target.':'Higher scores are the target.' }} {{ row.timeframe }} {{ row.current==null?'No current score has been recorded.':'Selected in this demo; not a measured clinical outcome.' }}</small></article></section>
 </section>
</template>
<script setup>
import {computed} from 'vue';
const props=defineProps({context:{type:Object,required:true},providerSigned:Boolean,supervisorSigned:Boolean,reviewer:{type:String,default:''}});
const fields=computed(()=>{const c=props.context,e=c.encounter;return [['Provider',`${c.provider.name}, ${c.provider.credential}`],['Service',`${e.serviceLabel} (${e.serviceCode})`],['Session time',`${e.time} · ${e.timezone}`],['Duration',`${e.durationMinutes} minutes`],['Client location',e.locationDetail],['Provider location',e.providerLocation],['Participants',e.participants],['Consent',e.consentSummary]];});
</script>
